<section>
    <div class="section-heading"><div><p class="eyebrow">Escalacoes da partida</p><h1><?= App\Core\View::e($match['home_team_name']) ?> x <?= App\Core\View::e($match['away_team_name']) ?></h1><p><?= App\Core\View::e($match['match_date'] ?: 'Data a definir') ?> <?= App\Core\View::e($match['match_time'] ?: '') ?></p></div></div>
    <?php if (!empty($message)): ?><p class="success" role="status"><?= App\Core\View::e($message) ?></p><?php endif; ?>
    <div class="lineup-summary-grid"><?php foreach ([['id' => $match['home_team_id'], 'name' => $match['home_team_name'], 'can' => $homeCanManage], ['id' => $match['away_team_id'], 'name' => $match['away_team_name'], 'can' => $awayCanManage]] as $team): ?><article class="panel"><h2><?= App\Core\View::e($team['name']) ?></h2><?php $item = null; foreach ($items as $candidate) if ((int) $candidate['team_id'] === (int) $team['id']) $item = $candidate; ?><?php if (!$item): ?><p>Escalação ainda não salva.</p><?php elseif ($item['status'] === 'confirmed'): ?><p><span class="status status-confirmed">confirmada</span></p><p><?= (int) $item['starters_count'] ?> titulares, <?= (int) $item['reserves_count'] ?> reservas<br><?= App\Core\View::e($item['formation_name']) ?></p><a href="<?= App\Core\View::e(App\Core\Config::url('/admin/partidas/' . $match['id'] . '/escalacao/' . $team['id'])) ?>">Visualizar escalação</a><?php else: ?><p>Rascunho privado da equipe.</p><?php endif; ?><?php if ($team['can']): ?><p><a class="button" href="<?= App\Core\View::e(App\Core\Config::url('/admin/partidas/' . $match['id'] . '/escalacao/' . $team['id'])) ?>">Gerenciar escalação</a></p><?php endif; ?></article><?php endforeach; ?></div>
    <p><a href="<?= App\Core\View::e(App\Core\Config::url('/admin/partidas/' . $match['id'])) ?>">Voltar para partida</a></p>
</section>
